describe('Pythagorean tiling with two square sizes and shared grout', () => {
  const p = proceduralMaterialPresets.pythagoreantiles;
  const field = (seed: number) => {
    const sample = createSurfaceSampler('pythagoreantiles', seed);
    return (x: number, y: number): SurfaceSample => {
      const out = {
        color: 0,
        height: 0,
        roughness: 0,
        occlusion: 0,
        mortar: 0,
        metallic: 0,
      };
      sample(x / 5, y / 5, out);
      return out;
    };
  };
  it.each([0, 1, 0xffffffff])(
    'keeps five large and five small square interiors unbroken by owner changes, with shared recessed joints for seed %s',
    (seed) => {
      const at = field(seed);
      for (const [x, y] of [
        [0, 0],
        [2, 1],
        [4, 2],
        [1, 3],
        [3, 4],
      ]) {
        for (const dx of [-0.75, 0, 0.75])
          for (const dy of [-0.75, 0, 0.75]) {
            const large = at(x + dx, y + dy);
            expect(large.mortar).toBe(0);
            expect(large.color).toBeGreaterThan(0.319);
            expect(large.color).toBeLessThan(0.421);
            expect(large.height).toBeGreaterThan(0.649 * p.relief);
            expect(large.height).toBeLessThan(0.654 * p.relief);
            expect(large.metallic).toBe(0);
          }
        for (const dx of [-0.3, 0, 0.3])
          for (const dy of [-0.3, 0, 0.3]) {
            const small = at(x + 0.5 + dx, y + 1.5 + dy);
            expect(small.mortar).toBe(0);
            expect(small.color).toBeGreaterThan(0.779);
            expect(small.color).toBeLessThan(0.861);
            expect(small.height).toBeGreaterThan(0.649 * p.relief);
            expect(small.height).toBeLessThan(0.654 * p.relief);
            expect(small.metallic).toBe(0);
          }
        const face = at(x, y),
          edge = at(x + 0.9775, y + 0.25);
        expect(edge.height).toBeGreaterThan(0.0005);
        expect(edge.height).toBeLessThan(0.0015);
        expect(edge.mortar).toBeGreaterThan(0);
        expect(edge.mortar).toBeLessThan(1);
        for (const joint of [at(x + 1, y), at(x + 1, y + 1.5)]) {
          expect(joint.mortar).toBe(1);
          expect(joint.height).toBe(0);
          expect(joint.occlusion).toBeCloseTo(0.5, 12);
          expect(joint.roughness - face.roughness).toBeGreaterThan(0.65);
        }
      }
    },
  );
  it('covers the periodic plane with both square sizes without overlaps or large missing regions', () => {
    for (const seed of [0, 1, 0xffffffff]) {
      const at = field(seed);
      let large = 0,
        small = 0,
        grout = 0;
      for (let y = 0; y < 256; y++)
        for (let x = 0; x < 256; x++) {
          const point = at(((x + 0.371) * 5) / 256, ((y + 0.619) * 5) / 256),
            cover = 1 - point.mortar;
          expect(point.mortar).toBeGreaterThanOrEqual(0);
          expect(point.mortar).toBeLessThanOrEqual(1);
          expect(point.height).toBeGreaterThanOrEqual(0);
          expect(point.height).toBeLessThan(0.654 * p.relief);
          if (cover > 0) {
            if (point.color / cover < 0.6) large += cover;
            else small += cover;
          }
          grout += point.mortar;
        }
      expect(large / 65536).toBeGreaterThan(0.75);
      expect(large / 65536).toBeLessThan(0.8);
      expect(small / 65536).toBeGreaterThan(0.17);
      expect(small / 65536).toBeLessThan(0.2);
      expect(grout / 65536).toBeGreaterThan(0.04);
      expect(grout / 65536).toBeLessThan(0.09);
      expect(large / small).toBeGreaterThan(4);
      expect(large / small).toBeLessThan(4.7);
    }
  });
  it('keeps square corners, grout T-junctions, lattice owner changes, grain and wrap C1', () => {
    const h = 1e-9;
    for (const seed of [0, 1, 0xffffffff]) {
      const sample = createSurfaceSampler('pythagoreantiles', seed);
      const at = (u: number, v: number): SurfaceSample => {
        const out = {
          color: 0,
          height: 0,
          roughness: 0,
          occlusion: 0,
          mortar: 0,
          metallic: 0,
        };
        sample(u, v, out);
        return out;
      };
      for (let y = 0; y <= 128; y++)
        for (let x = 0; x <= 128; x++)
          for (const axis of [0, 1]) {
            const u = x / 128,
              v = y / 128,
              a = at(u - (axis ? 0 : h), v - (axis ? h : 0)),
              b = at(u, v),
              c = at(u + (axis ? 0 : h), v + (axis ? h : 0));
            for (const key of [
              'color',
              'height',
              'roughness',
              'occlusion',
              'mortar',
            ] as const)
              expect(Math.abs((c[key] - 2 * b[key] + a[key]) / h)).toBeLessThan(
                0.02,
              );
          }
    }
  });
});

describe('Crinoid fossil ossicles with five-lobed lumens and radial ribs', () => {
  const p = proceduralMaterialPresets.crinoidossicles;
  const field = (seed: number) => {
    const sample = createSurfaceSampler('crinoidossicles', seed);
    return (col: number, row: number, x: number, y: number): SurfaceSample => {
      const out = {
        color: 0,
        height: 0,
        roughness: 0,
        occlusion: 0,
        mortar: 0,
        metallic: 0,
      };
      sample((col + 0.5 + x) / p.cells, (row + 0.5 + y) / p.cells, out);
      return out;
    };
  };
  it.each([0, 1, 0xffffffff])(
    'retains five filled lumen lobes, twenty shallow articular ribs and a continuous stone matrix for seed %s',
    (seed) => {
      const at = field(seed);
      for (let row = 0; row < p.cells; row++)
        for (let col = 0; col < p.cells; col++) {
          const matrix = at(col, row, 0.42, 0),
            center = at(col, row, 0, 0),
            lobes: boolean[] = [],
            profile: number[] = [];
          let minStar = Infinity,
            maxStar = -Infinity,
            minRoughness = Infinity,
            maxRoughness = -Infinity,
            minAO = Infinity,
            maxAO = -Infinity;
          expect(matrix.height - center.height).toBeGreaterThan(0.000059);
          expect(center.height).toBeGreaterThan(0.309 * p.relief);
          expect(center.occlusion).toBeCloseTo(0.72, 12);
          expect(center.roughness - matrix.roughness).toBeGreaterThan(0.05);
          for (let j = 0; j < 720; j++) {
            const angle = (Math.PI * 2 * j) / 720,
              x = Math.cos(angle),
              y = Math.sin(angle),
              star = at(col, row, 0.1 * x, 0.1 * y),
              ring = at(col, row, 0.22 * x, 0.22 * y);
            lobes.push(star.height < 0.34 * p.relief);
            profile.push(ring.height);
            minStar = Math.min(minStar, star.height);
            maxStar = Math.max(maxStar, star.height);
            minRoughness = Math.min(minRoughness, ring.roughness);
            maxRoughness = Math.max(maxRoughness, ring.roughness);
            minAO = Math.min(minAO, ring.occlusion);
            maxAO = Math.max(maxAO, ring.occlusion);
            expect(ring.height - matrix.height).toBeGreaterThan(0.00017);
            expect(star.metallic).toBe(0);
            expect(ring.metallic).toBe(0);
          }
          let lumenLobes = 0;
          for (let j = 0; j < lobes.length; j++)
            if (lobes[j] && !lobes[(j + lobes.length - 1) % lobes.length])
              lumenLobes++;
          expect(lumenLobes).toBe(5);
          expect(maxStar - minStar).toBeGreaterThan(0.00025);
          expect(maxRoughness - minRoughness).toBeGreaterThan(0.029);
          expect(maxAO - minAO).toBeGreaterThan(0.024);
          const maximum = Math.max(...profile),
            minimum = Math.min(...profile),
            start = profile.indexOf(maximum);
          expect(maximum - minimum).toBeGreaterThan(0.000095);
          let high = true,
            ribs = 0;
          for (let j = 1; j <= profile.length; j++) {
            const value = profile[(start + j) % profile.length];
            if (high && value < 0.51 * p.relief) high = false;
            else if (!high && value > 0.55 * p.relief) {
              high = true;
              ribs++;
            }
          }
          expect(ribs).toBe(20);
          expect(matrix.metallic).toBe(0);
          expect(center.metallic).toBe(0);
        }
    },
  );
  it('keeps the masked angular pole, star lumen, radial ribs, disc bevels, matrix and wrap C1', () => {
    const h = 1e-9;
    for (const seed of [0, 1, 0xffffffff]) {
      const sample = createSurfaceSampler('crinoidossicles', seed);
      const at = (u: number, v: number): SurfaceSample => {
        const out = {
          color: 0,
          height: 0,
          roughness: 0,
          occlusion: 0,
          mortar: 0,
          metallic: 0,
        };
        sample(u, v, out);
        return out;
      };
      for (let y = 0; y <= 128; y++)
        for (let x = 0; x <= 128; x++)
          for (const axis of [0, 1]) {
            const u = x / 128,
              v = y / 128,
              a = at(u - (axis ? 0 : h), v - (axis ? h : 0)),
              b = at(u, v),
              c = at(u + (axis ? 0 : h), v + (axis ? h : 0));
            for (const key of [
              'color',
              'height',
              'roughness',
              'occlusion',
            ] as const)
              expect(Math.abs((c[key] - 2 * b[key] + a[key]) / h)).toBeLessThan(
                0.02,
              );
          }
    }
  });
});

describe('Stamped can lids with raised twin-hole pull tabs and rivets', () => {
  const p = proceduralMaterialPresets.canlids;
  const field = (seed: number) => {
    const sample = createSurfaceSampler('canlids', seed);
    return (col: number, row: number, x: number, y: number): SurfaceSample => {
      const out = {
        color: 0,
        height: 0,
        roughness: 0,
        occlusion: 0,
        mortar: 0,
        metallic: 0,
      };
      const turn = (col + row) & 1;
      sample(
        (col + 0.5 + (turn ? y : x)) / p.cells,
        (row + 0.5 + (turn ? x : y)) / p.cells,
        out,
      );
      return out;
    };
  };
  it.each([0, 1, 0xffffffff])(
    'preserves raised stamped beads, recessed scoring, two lid-backed tab openings and a higher rivet for seed %s',
    (seed) => {
      const at = field(seed);
      for (let row = 0; row < p.cells; row++)
        for (let col = 0; col < p.cells; col++) {
          const backing = at(col, row, 0.4, 0),
            face = at(col, row, 0.18, 0),
            bead = at(col, row, 0.29, 0),
            score = at(col, row, 0.235, 0),
            bridge = at(col, row, 0, -0.035),
            grip = at(col, row, 0, -0.115),
            slot = at(col, row, 0.026, 0.027),
            rivet = at(col, row, 0, 0.03);
          expect(backing.height).toBeCloseTo(0.025 * p.relief, 12);
          expect(face.height).toBeGreaterThan(0.379 * p.relief);
          expect(face.height).toBeLessThan(0.384 * p.relief);
          expect(bead.height - face.height).toBeGreaterThan(0.00037);
          expect(face.roughness - bead.roughness).toBeGreaterThan(0.039);
          expect(face.height - score.height).toBeGreaterThan(0.00012);
          expect(score.roughness - face.roughness).toBeGreaterThan(0.069);
          expect(face.occlusion - score.occlusion).toBeGreaterThan(0.095);
          expect(bridge.height - face.height).toBeGreaterThan(0.001);
          expect(face.roughness - bridge.roughness).toBeGreaterThan(0.08);
          for (const opening of [grip, slot]) {
            expect(opening.height).toBeGreaterThan(0.379 * p.relief);
            expect(opening.height).toBeLessThan(0.384 * p.relief);
            expect(bridge.height - opening.height).toBeGreaterThan(0.001);
            expect(opening.occlusion).toBeCloseTo(0.96, 12);
          }
          expect(rivet.height - bridge.height).toBeGreaterThan(0.0004);
          expect(rivet.height).toBeLessThan(0.772 * p.relief);
          expect(rivet.roughness).toBeLessThan(bridge.roughness);
          for (const point of [
            backing,
            face,
            bead,
            score,
            bridge,
            grip,
            slot,
            rivet,
          ])
            expect(point.metallic).toBe(1);
        }
    },
  );
  it('keeps lid bevels, stamped rings, tab holes, rivet joins, grain and tile wrap C1', () => {
    const h = 1e-9;
    for (const seed of [0, 1, 0xffffffff]) {
      const sample = createSurfaceSampler('canlids', seed);
      const at = (u: number, v: number): SurfaceSample => {
        const out = {
          color: 0,
          height: 0,
          roughness: 0,
          occlusion: 0,
          mortar: 0,
          metallic: 0,
        };
        sample(u, v, out);
        return out;
      };
      for (let y = 0; y <= 128; y++)
        for (let x = 0; x <= 128; x++)
          for (const axis of [0, 1]) {
            const u = x / 128,
              v = y / 128,
              a = at(u - (axis ? 0 : h), v - (axis ? h : 0)),
              b = at(u, v),
              c = at(u + (axis ? 0 : h), v + (axis ? h : 0));
            for (const key of [
              'color',
              'height',
              'roughness',
              'occlusion',
            ] as const)
              expect(Math.abs((c[key] - 2 * b[key] + a[key]) / h)).toBeLessThan(
                0.02,
              );
          }
    }
  });
});

describe('Pale spalted wood with dark zone lines and continuous grain', () => {
  const p = proceduralMaterialPresets.spaltedwood;
  it.each([0, 1, 0xffffffff])(
    'retains sparse dark zone lines over pale longitudinal grain without carving deep cracks for seed %s',
    (seed) => {
      const sample = createSurfaceSampler('spaltedwood', seed),
        out = {
          color: 0,
          height: 0,
          roughness: 0,
          occlusion: 0,
          mortar: 0,
          metallic: 0,
        };
      let darkCount = 0,
        paleCount = 0,
        darkHeight = 0,
        paleHeight = 0,
        minimumColor = Infinity,
        maximumColor = -Infinity,
        minimumHeight = Infinity,
        maximumHeight = -Infinity;
      for (let y = 0; y < 128; y++)
        for (let x = 0; x < 128; x++) {
          sample((x + 0.37) / 128, (y + 0.61) / 128, out);
          minimumColor = Math.min(minimumColor, out.color);
          maximumColor = Math.max(maximumColor, out.color);
          minimumHeight = Math.min(minimumHeight, out.height);
          maximumHeight = Math.max(maximumHeight, out.height);
          if (out.color < 0.35) {
            darkCount++;
            darkHeight += out.height / p.relief;
          }
          if (out.color > 0.72) {
            paleCount++;
            paleHeight += out.height / p.relief;
          }
          expect(out.height).toBeGreaterThanOrEqual(0.64 * p.relief);
          expect(out.height).toBeLessThanOrEqual(0.668 * p.relief);
          expect(out.roughness).toBeGreaterThanOrEqual(0.67);
          expect(out.roughness).toBeLessThanOrEqual(0.73);
          expect(out.occlusion).toBeGreaterThanOrEqual(0.97);
          expect(out.occlusion).toBeLessThanOrEqual(0.99);
          expect(out.metallic).toBe(0);
        }
      expect(darkCount).toBeGreaterThan(128 * 128 * 0.005);
      expect(darkCount).toBeLessThan(128 * 128 * 0.2);
      expect(paleCount).toBeGreaterThan(128 * 128 * 0.7);
      expect(minimumColor).toBeLessThan(0.27);
      expect(maximumColor).toBeGreaterThan(0.86);
      expect(maximumHeight - minimumHeight).toBeGreaterThan(0.00005);
      expect(
        Math.abs(darkHeight / darkCount - paleHeight / paleCount),
      ).toBeLessThan(0.008);
    },
  );
  it('keeps variable-width spalt lines, coarse zone joins, fine longitudinal grain and wrap C1', () => {
    const h = 1e-9;
    for (const seed of [0, 1, 0xffffffff]) {
      const sample = createSurfaceSampler('spaltedwood', seed);
      const at = (u: number, v: number): SurfaceSample => {
        const out = {
          color: 0,
          height: 0,
          roughness: 0,
          occlusion: 0,
          mortar: 0,
          metallic: 0,
        };
        sample(u, v, out);
        return out;
      };
      for (let y = 0; y <= 128; y++)
        for (let x = 0; x <= 128; x++)
          for (const axis of [0, 1]) {
            const u = x / 128,
              v = y / 128,
              a = at(u - (axis ? 0 : h), v - (axis ? h : 0)),
              b = at(u, v),
              c = at(u + (axis ? 0 : h), v + (axis ? h : 0));
            for (const key of [
              'color',
              'height',
              'roughness',
              'occlusion',
            ] as const)
              expect(Math.abs((c[key] - 2 * b[key] + a[key]) / h)).toBeLessThan(
                0.02,
              );
          }
    }
  });
});

