describe('Steel grinding burrs with six curved lands and mounting holes', () => {
  const p = proceduralMaterialPresets.grinderburrs;
  const field = (seed: number) => {
    const sample = createSurfaceSampler('grinderburrs', seed);
    return (col: number, row: number, x: number, y: number): SurfaceSample => {
      const out = {
        color: 0,
        height: 0,
        roughness: 0,
        occlusion: 0,
        mortar: 0,
        metallic: 0,
      };
      sample((col + 0.5 + x) / p.cells, (row + 0.5 + y) / p.cells, out);
      return out;
    };
  };
  it.each([0, 1, 0xffffffff])(
    'retains six raised smoother lands over filled grooves, one central bore and three opaque mounting holes for seed %s',
    (seed) => {
      const at = field(seed);
      for (let row = 0; row < p.cells; row++)
        for (let col = 0; col < p.cells; col++) {
          const backing = at(col, row, 0.4, 0),
            bore = at(col, row, 0, 0),
            profile: number[] = [];
          expect(bore.height).toBeCloseTo(backing.height, 12);
          expect(bore.occlusion).toBeCloseTo(0.35, 12);
          let minimum = Infinity,
            maximum = -Infinity,
            minRoughness = Infinity,
            maxRoughness = -Infinity,
            minAO = Infinity,
            maxAO = -Infinity,
            holes = 0;
          const holeFlags: boolean[] = [];
          for (let i = 0; i < 720; i++) {
            const angle = (Math.PI * 2 * i) / 720,
              x = Math.cos(angle),
              y = Math.sin(angle),
              land = at(col, row, 0.16 * x, 0.16 * y),
              opening = at(col, row, p.holeDistance * x, p.holeDistance * y);
            profile.push(land.height);
            holeFlags.push(opening.height < 0.0003);
            minimum = Math.min(minimum, land.height);
            maximum = Math.max(maximum, land.height);
            minRoughness = Math.min(minRoughness, land.roughness);
            maxRoughness = Math.max(maxRoughness, land.roughness);
            minAO = Math.min(minAO, land.occlusion);
            maxAO = Math.max(maxAO, land.occlusion);
            expect(land.metallic).toBe(1);
            expect(opening.metallic).toBe(1);
          }
          for (let i = 0; i < holeFlags.length; i++)
            if (
              holeFlags[i] &&
              !holeFlags[(i + holeFlags.length - 1) % holeFlags.length]
            )
              holes++;
          expect(holes).toBe(3);
          expect(minimum - backing.height).toBeGreaterThan(0.00165);
          expect(maximum - minimum).toBeGreaterThan(0.00095);
          expect(maxRoughness - minRoughness).toBeGreaterThan(0.29);
          expect(minAO).toBeLessThan(0.761);
          expect(maxAO).toBeGreaterThan(0.979);
          const start = profile.indexOf(maximum);
          let high = true,
            crests = 0;
          for (let j = 1; j <= profile.length; j++) {
            const value = profile[(start + j) % profile.length];
            if (high && value < 0.47 * p.relief) high = false;
            else if (!high && value > 0.65 * p.relief) {
              high = true;
              crests++;
            }
          }
          expect(crests).toBe(6);
          expect(backing.metallic).toBe(1);
        }
    },
  );
  it('curves the six lands in the same direction across radii instead of painting straight radial spokes', () => {
    for (const seed of [0, 1, 0xffffffff]) {
      const at = field(seed),
        inner: number[] = [],
        outer: number[] = [];
      for (let i = 0; i < 720; i++) {
        const angle = (Math.PI * 2 * i) / 720,
          x = Math.cos(angle),
          y = Math.sin(angle);
        inner.push(at(0, 0, 0.12 * x, 0.12 * y).height);
        outer.push(at(0, 0, 0.21 * x, 0.21 * y).height);
      }
      const innerMean = inner.reduce((a, b) => a + b) / inner.length,
        outerMean = outer.reduce((a, b) => a + b) / outer.length;
      let bestLag = 0,
        bestScore = -Infinity;
      for (let lag = -60; lag <= 60; lag++) {
        let score = 0;
        for (let i = 0; i < inner.length; i++)
          score +=
            (inner[i] - innerMean) *
            (outer[(i + lag + outer.length) % outer.length] - outerMean);
        if (score > bestScore) {
          bestScore = score;
          bestLag = lag;
        }
      }
      expect(bestLag).toBeGreaterThanOrEqual(-24);
      expect(bestLag).toBeLessThanOrEqual(-19);
    }
  });
  it('keeps curved land joins, angular branch, masked center, ring bevels, mounting holes, grain and wrap C1', () => {
    const h = 1e-9;
    for (const seed of [0, 1, 0xffffffff]) {
      const sample = createSurfaceSampler('grinderburrs', seed);
      const at = (u: number, v: number): SurfaceSample => {
        const out = {
          color: 0,
          height: 0,
          roughness: 0,
          occlusion: 0,
          mortar: 0,
          metallic: 0,
        };
        sample(u, v, out);
        return out;
      };
      for (let y = 0; y <= 128; y++)
        for (let x = 0; x <= 128; x++)
          for (const axis of [0, 1]) {
            const u = x / 128,
              v = y / 128,
              a = at(u - (axis ? 0 : h), v - (axis ? h : 0)),
              b = at(u, v),
              c = at(u + (axis ? 0 : h), v + (axis ? h : 0));
            for (const key of [
              'color',
              'height',
              'roughness',
              'occlusion',
            ] as const)
              expect(Math.abs((c[key] - 2 * b[key] + a[key]) / h)).toBeLessThan(
                0.02,
              );
          }
    }
  });
});

describe('Serrated ivory shark tooth crowns with rough double roots', () => {
  const p = proceduralMaterialPresets.sharkteeth;
  const field = (seed: number) => {
    const sample = createSurfaceSampler('sharkteeth', seed);
    return (col: number, row: number, x: number, y: number): SurfaceSample => {
      const vertical = (row + col) & 1,
        out = {
          color: 0,
          height: 0,
          roughness: 0,
          occlusion: 0,
          mortar: 0,
          metallic: 0,
        };
      sample(
        (col + 0.5 + (vertical ? x : y)) / p.cells,
        (row + 0.5 + (vertical ? y : x)) / p.cells,
        out,
      );
      return out;
    };
  };
  it.each([0, 1, 0xffffffff])(
    'retains a pointed widening enamel crown, serrations on both edges, two lower rough root lobes, open root notch and connected neck for seed %s',
    (seed) => {
      const at = field(seed);
      for (let row = 0; row < p.cells; row++)
        for (let col = 0; col < p.cells; col++) {
          const gap = at(col, row, 0.26, 0),
            enamel = at(col, row, 0, -0.12),
            notch = at(col, row, 0, 0.27);
          expect(enamel.height).toBeGreaterThan(0.004139);
          expect(enamel.height).toBeLessThan(0.004147);
          expect(enamel.roughness).toBeLessThan(0.286);
          expect(enamel.metallic).toBe(0);
          expect(at(col, row, 0.06, -0.25).height).toBeCloseTo(gap.height, 12);
          expect(at(col, row, 0.06, -0.1).height - gap.height).toBeGreaterThan(
            0.0031,
          );
          expect(notch.height).toBeCloseTo(gap.height, 12);
          expect(notch.occlusion).toBeCloseTo(0.35, 12);
          for (const side of [-1, 1]) {
            const root = at(col, row, side * p.rootOffset, p.rootY),
              rootEnd = at(col, row, side * p.rootOffset, 0.27);
            expect(enamel.height - root.height).toBeGreaterThan(0.00107);
            expect(enamel.color - root.color).toBeGreaterThan(0.26);
            expect(root.roughness - enamel.roughness).toBeGreaterThan(0.38);
            expect(rootEnd.height - gap.height).toBeGreaterThan(0.0026);
            let peak = 0,
              trough = Infinity,
              falling = false,
              pullbacks = 0;
            for (let i = 0; i <= 240; i++) {
              const y = -0.19 + (0.27 * i) / 240;
              let low = 0,
                high = 0.23;
              for (let j = 0; j < 16; j++) {
                const middle = (low + high) * 0.5;
                if (at(col, row, side * middle, y).height > 0.001) low = middle;
                else high = middle;
              }
              if (falling) {
                trough = Math.min(trough, low);
                if (low - trough > 0.0005) {
                  falling = false;
                  peak = low;
                }
              } else {
                peak = Math.max(peak, low);
                if (peak - low > 0.0005) {
                  pullbacks++;
                  falling = true;
                  trough = low;
                }
              }
            }
            expect(pullbacks).toBeGreaterThanOrEqual(4);
            expect(pullbacks).toBeLessThanOrEqual(6);
          }
          for (let i = 0; i <= 47; i++) {
            const joined = at(col, row, 0, -0.24 + i * 0.01);
            expect(joined.height - gap.height).toBeGreaterThan(0.00188);
            expect(joined.height).toBeLessThan(0.004147);
          }
          for (const [x, y] of [
            [-0.26, 0],
            [0, -0.38],
            [0, 0.33],
          ]) {
            const backing = at(col, row, x, y);
            expect(backing.height).toBeCloseTo(gap.height, 12);
            expect(backing.occlusion).toBeCloseTo(0.35, 12);
          }
        }
    },
  );
  it('keeps pointed enamel, periodic serrations, root overlap, neck joins, open notch, grain and wrap C1', () => {
    const h = 1e-9;
    for (const seed of [0, 1, 0xffffffff]) {
      const sample = createSurfaceSampler('sharkteeth', seed);
      const at = (u: number, v: number): SurfaceSample => {
        const out = {
          color: 0,
          height: 0,
          roughness: 0,
          occlusion: 0,
          mortar: 0,
          metallic: 0,
        };
        sample(u, v, out);
        return out;
      };
      for (let y = 0; y <= 128; y++)
        for (let x = 0; x <= 128; x++)
          for (const axis of [0, 1]) {
            const u = x / 128,
              v = y / 128,
              a = at(u - (axis ? 0 : h), v - (axis ? h : 0)),
              b = at(u, v),
              c = at(u + (axis ? 0 : h), v + (axis ? h : 0));
            for (const key of [
              'color',
              'height',
              'roughness',
              'occlusion',
            ] as const)
              expect(Math.abs((c[key] - 2 * b[key] + a[key]) / h)).toBeLessThan(
                0.02,
              );
          }
    }
  });
});

describe('Three-lobed green bell pepper crosscuts with pith and attached seeds', () => {
  const p = proceduralMaterialPresets.bellpepperslices;
  const field = (seed: number) => {
    const sample = createSurfaceSampler('bellpepperslices', seed);
    return (col: number, row: number, x: number, y: number): SurfaceSample => {
      const vertical = (row + col) & 1,
        out = {
          color: 0,
          height: 0,
          roughness: 0,
          occlusion: 0,
          mortar: 0,
          metallic: 0,
        };
      sample(
        (col + 0.5 + (vertical ? x : y)) / p.cells,
        (row + 0.5 + (vertical ? y : x)) / p.cells,
        out,
      );
      return out;
    };
  };
  it.each([0, 1, 0xffffffff])(
    'retains a three-lobed raised ring, lower pale connected pith, three open chambers and six convex attached seeds for seed %s',
    (seed) => {
      const at = field(seed);
      for (let row = 0; row < p.cells; row++)
        for (let col = 0; col < p.cells; col++) {
          const gap = at(col, row, 0.4, 0),
            core = at(col, row, 0, 0);
          expect(core.height - gap.height).toBeGreaterThan(0.00176);
          expect(core.color).toBeGreaterThan(0.909);
          for (let lobe = 0; lobe < 3; lobe++) {
            const angle = (Math.PI * 2 * lobe) / 3,
              ax = Math.cos(angle),
              ay = Math.sin(angle),
              atLocal = (along: number, across: number) =>
                at(
                  col,
                  row,
                  along * ax - across * ay,
                  along * ay + across * ax,
                ),
              wall = atLocal(0.2775, 0),
              pith = atLocal(0.11, 0),
              bulge = atLocal(0.29, 0),
              betweenAngle = angle + Math.PI / 3,
              recess = at(
                col,
                row,
                0.13 * Math.cos(betweenAngle),
                0.13 * Math.sin(betweenAngle),
              ),
              outsideLobe = at(
                col,
                row,
                0.29 * Math.cos(betweenAngle),
                0.29 * Math.sin(betweenAngle),
              );
            expect(wall.height - gap.height).toBeGreaterThan(0.0035);
            expect(wall.height - pith.height).toBeGreaterThan(0.00171);
            expect(pith.color - wall.color).toBeGreaterThan(0.57);
            expect(pith.roughness - wall.roughness).toBeGreaterThan(0.17);
            expect(wall.metallic).toBe(0);
            expect(bulge.height - gap.height).toBeGreaterThan(0.0022);
            expect(recess.height).toBeCloseTo(gap.height, 12);
            expect(recess.occlusion).toBeCloseTo(0.3, 12);
            expect(outsideLobe.height).toBeCloseTo(gap.height, 12);
            for (let i = 0; i <= 26; i++) {
              const membrane = atLocal(i * 0.01, 0);
              expect(membrane.height - gap.height).toBeGreaterThan(0.00176);
              expect(membrane.height).toBeLessThan(0.003685);
            }
            for (const side of [-1, 1]) {
              const seedCenter = atLocal(p.seedAlong, side * p.seedOffset),
                seedShoulder = atLocal(
                  p.seedAlong + p.seedLength * 0.7,
                  side * p.seedOffset,
                );
              expect(seedCenter.height - pith.height).toBeGreaterThan(0.00105);
              expect(seedCenter.height - seedShoulder.height).toBeGreaterThan(
                0.00019,
              );
              expect(seedCenter.color).toBeGreaterThan(0.959);
              expect(seedCenter.roughness).toBeLessThan(pith.roughness);
              expect(seedCenter.occlusion).toBeCloseTo(0.96, 12);
            }
          }
        }
    },
  );
  it('keeps three-lobed ring joins, hollow chamber edges, membrane junctions, seed shoulders, grain and wrap C1', () => {
    const h = 1e-9;
    for (const seed of [0, 1, 0xffffffff]) {
      const sample = createSurfaceSampler('bellpepperslices', seed);
      const at = (u: number, v: number): SurfaceSample => {
        const out = {
          color: 0,
          height: 0,
          roughness: 0,
          occlusion: 0,
          mortar: 0,
          metallic: 0,
        };
        sample(u, v, out);
        return out;
      };
      for (let y = 0; y <= 128; y++)
        for (let x = 0; x <= 128; x++)
          for (const axis of [0, 1]) {
            const u = x / 128,
              v = y / 128,
              a = at(u - (axis ? 0 : h), v - (axis ? h : 0)),
              b = at(u, v),
              c = at(u + (axis ? 0 : h), v + (axis ? h : 0));
            for (const key of [
              'color',
              'height',
              'roughness',
              'occlusion',
            ] as const)
              expect(Math.abs((c[key] - 2 * b[key] + a[key]) / h)).toBeLessThan(
                0.02,
              );
          }
    }
  });
});

