describe('Radially pleated paper folding fans with exposed wooden ribs', () => {
  const p = proceduralMaterialPresets.foldingfans;
  const field = (seed: number) => {
    const sample = createSurfaceSampler('foldingfans', seed);
    return (x: number, y: number): SurfaceSample => {
      const out = {
        color: 0,
        height: 0,
        roughness: 0,
        occlusion: 0,
        mortar: 0,
        metallic: 0,
      };
      sample(x / p.cells, y / p.cells, out);
      return out;
    };
  };
  it.each([0, 1, 0xffffffff])(
    'preserves twelve radial paper folds, thirteen exposed ribs, guard edges, pivot caps and opaque open backing for seed %s',
    (seed) => {
      const at = field(seed);
      for (let row = 0; row < p.cells; row++)
        for (let col = 0; col < p.cells; col++) {
          const flip = (col + row) & 1 ? -1 : 1;
          const radial = (r: number, a: number) =>
            at(
              col + 0.5 + r * Math.sin(a) * flip,
              row + 0.5 + (p.pivotY - r * Math.cos(a)) * flip,
            );
          const step = (2 * p.halfAngle) / p.folds;
          for (let i = 1; i < p.folds; i++) {
            const a = -p.halfAngle + i * step;
            for (const r of [0.24, 0.33, 0.39]) {
              const crest = radial(r, a),
                trough = radial(r, a + step * 0.5);
              expect(crest.height - trough.height).toBeGreaterThan(0.00177);
              expect(crest.color - trough.color).toBeGreaterThan(0.14);
              expect(trough.roughness - crest.roughness).toBeGreaterThan(0.065);
              expect(crest.occlusion - trough.occlusion).toBeGreaterThan(0.17);
              expect(crest.metallic).toBe(0);
            }
          }
          for (let i = 0; i <= p.folds; i++) {
            const a = -p.halfAngle + i * step,
              rib = radial(0.12, a);
            expect(rib.height).toBeCloseTo(0.25 * p.relief, 12);
            expect(rib.occlusion).toBeCloseTo(0.94, 12);
            if (i < p.folds) {
              const gap = radial(0.12, a + step * 0.5);
              expect(gap.height).toBeCloseTo(0.025 * p.relief, 12);
              expect(rib.color - gap.color).toBeGreaterThan(0.4);
            }
          }
          for (const a of [-p.halfAngle, p.halfAngle]) {
            const guard = radial(0.35, a),
              outside = radial(0.35, a + Math.sign(a) * 0.05);
            expect(guard.height).toBeCloseTo(0.25 * p.relief, 12);
            expect(outside.height).toBeCloseTo(0.025 * p.relief, 12);
          }
          const pivot = radial(0, 0);
          expect(pivot.height).toBeCloseTo(0.3 * p.relief, 12);
          expect(radial(0.45, 0).height).toBeCloseTo(0.025 * p.relief, 12);
          expect(radial(0.1, Math.PI).height).toBeCloseTo(0.025 * p.relief, 12);
        }
    },
  );
  it('keeps annular paper, radial pleats, hidden rib ties, pivot caps, cell owners and wrap C1', () => {
    // Narrow rib shoulders have high finite curvature; this step resolves
    // their converging gradients without relaxing the discontinuity bound.
    const h = 1e-9;
    for (const seed of [0, 1, 0xffffffff]) {
      const at = field(seed);
      for (let y = 0; y <= 128; y++)
        for (let x = 0; x <= 128; x++)
          for (const axis of [0, 1]) {
            const u = (x * p.cells) / 128,
              v = (y * p.cells) / 128,
              a = at(u - (axis ? 0 : h), v - (axis ? h : 0)),
              b = at(u, v),
              c = at(u + (axis ? 0 : h), v + (axis ? h : 0));
            for (const key of [
              'color',
              'height',
              'roughness',
              'occlusion',
            ] as const)
              expect(Math.abs((c[key] - 2 * b[key] + a[key]) / h)).toBeLessThan(
                0.02,
              );
          }
    }
  });
});

describe('Succulent rosettes with three raised fleshy leaf whorls', () => {
  const p = proceduralMaterialPresets.succulentrosettes;
  const field = (seed: number) => {
    const sample = createSurfaceSampler('succulentrosettes', seed);
    return (x: number, y: number): SurfaceSample => {
      const out = {
        color: 0,
        height: 0,
        roughness: 0,
        occlusion: 0,
        mortar: 0,
        metallic: 0,
      };
      sample(x / p.cells, y / p.cells, out);
      return out;
    };
  };
  it.each([0, 1, 0xffffffff])(
    'preserves six outer lobes, staggered taller inner whorls, convex spoon leaves and clear backing for seed %s',
    (seed) => {
      const at = field(seed);
      for (let row = 0; row < p.cells; row++)
        for (let col = 0; col < p.cells; col++) {
          const probe = (x: number, y: number) =>
            at(col + 0.5 + x, row + 0.5 + y);
          const occupied: boolean[] = [];
          let peak = -Infinity,
            phase = 0;
          for (let i = 0; i < 720; i++) {
            const a = (i * 2 * Math.PI) / 720,
              c = Math.cos(a),
              s = Math.sin(a),
              value = probe(0.31 * c, 0.31 * s).height;
            occupied.push(probe(0.32 * c, 0.32 * s).height > 0.004);
            if (value > peak) {
              peak = value;
              phase = a;
            }
          }
          let groups = 0;
          for (let i = 0; i < occupied.length; i++)
            if (
              occupied[i] &&
              !occupied[(i + occupied.length - 1) % occupied.length]
            )
              groups++;
          expect(groups).toBe(6);
          for (let i = 0; i < 6; i++) {
            const a = phase + (i * 2 * Math.PI) / 6,
              c = Math.cos(a),
              s = Math.sin(a),
              ma = a + Math.PI / 6,
              outer = probe(0.31 * c, 0.31 * s),
              middle = probe(0.2 * Math.cos(ma), 0.2 * Math.sin(ma)),
              inner = probe(0.09 * c, 0.09 * s),
              outside = probe(0.43 * c, 0.43 * s);
            expect(outer.height).toBeGreaterThan(0.009);
            expect(outer.height).toBeLessThan(0.013);
            expect(middle.height - outer.height).toBeGreaterThan(0.004);
            expect(inner.height - middle.height).toBeGreaterThan(0.004);
            expect(inner.color - outer.color).toBeGreaterThan(0.025);
            expect(outside.height).toBeCloseTo(0.025 * p.relief, 12);
            expect(outside.roughness - outer.roughness).toBeGreaterThan(0.48);
            expect(outer.occlusion - outside.occlusion).toBeGreaterThan(0.55);
            expect(inner.metallic).toBe(0);
            for (const side of [-1, 1]) {
              const flank = probe(
                0.31 * c - side * 0.05 * s,
                0.31 * s + side * 0.05 * c,
              );
              expect(outer.height - flank.height).toBeGreaterThan(0.0011);
              expect(outer.occlusion - flank.occlusion).toBeGreaterThan(0.03);
            }
          }
        }
    },
  );
  it('keeps spoon tips, tapered widths, layered whorls, cell owners and wrap C1', () => {
    const h = 1e-8;
    for (const seed of [0, 1, 0xffffffff]) {
      const at = field(seed);
      for (let y = 0; y <= 128; y++)
        for (let x = 0; x <= 128; x++)
          for (const axis of [0, 1]) {
            const u = (x * p.cells) / 128,
              v = (y * p.cells) / 128,
              a = at(u - (axis ? 0 : h), v - (axis ? h : 0)),
              b = at(u, v),
              c = at(u + (axis ? 0 : h), v + (axis ? h : 0));
            for (const key of [
              'color',
              'height',
              'roughness',
              'occlusion',
            ] as const)
              expect(Math.abs((c[key] - 2 * b[key] + a[key]) / h)).toBeLessThan(
                0.02,
              );
          }
    }
  });
});

describe('Meandering spherical metal ball pull chains', () => {
  const p = proceduralMaterialPresets.ballchain;
  const field = (seed: number) => {
    const sample = createSurfaceSampler('ballchain', seed);
    return (x: number, y: number): SurfaceSample => {
      const out = {
        color: 0,
        height: 0,
        roughness: 0,
        occlusion: 0,
        mortar: 0,
        metallic: 0,
      };
      sample(x / p.columns, y / (p.rows * p.pitch), out);
      return out;
    };
  };
  it.each([0, 1, 0xffffffff])(
    'keeps solid spherical crowns, a real meander and continuous lower narrow connectors through wrap for seed %s',
    (seed) => {
      const at = field(seed);
      for (let col = 0; col < p.columns; col++) {
        const centers: number[] = [];
        for (let row = 0; row < p.rows; row++) {
          const y = (row + 0.5) * p.pitch;
          let best = -Infinity,
            center = 0;
          for (let i = 0; i <= 256; i++) {
            const x = col + 0.2 + (0.6 * i) / 256,
              value = at(x, y).height;
            if (value > best) {
              best = value;
              center = x;
            }
          }
          centers.push(center);
          const crown = at(center, y),
            radialHeights: number[] = [];
          expect(crown.height).toBeGreaterThan(0.00496);
          expect(crown.metallic).toBe(1);
          for (let i = 0; i < 32; i++) {
            const a = (i * 2 * Math.PI) / 32,
              side = at(center + 0.12 * Math.cos(a), y + 0.12 * Math.sin(a));
            expect(crown.height - side.height).toBeGreaterThan(0.0009);
            expect(side.metallic).toBe(1);
            radialHeights.push(side.height);
          }
          expect(
            Math.max(...radialHeights) - Math.min(...radialHeights),
          ).toBeLessThan(0.00007);
        }
        expect(Math.max(...centers) - Math.min(...centers)).toBeGreaterThan(
          0.16,
        );
        for (let row = 0; row < p.rows; row++) {
          const x = (centers[row] + centers[(row + 1) % p.rows]) * 0.5,
            y = (row + 1) * p.pitch,
            dx = centers[(row + 1) % p.rows] - centers[row],
            length = Math.hypot(dx, p.pitch),
            nx = -p.pitch / length,
            ny = dx / length,
            link = at(x, y),
            crown = at(centers[row], (row + 0.5) * p.pitch);
          expect(link.height).toBeGreaterThan(0.00124);
          expect(link.height).toBeLessThan(0.00128);
          expect(crown.height - link.height).toBeGreaterThan(0.00365);
          expect(link.occlusion).toBeGreaterThan(0.91);
          expect(link.roughness - crown.roughness).toBeGreaterThan(0.09);
          for (const side of [-1, 1]) {
            const backing = at(x + side * 0.04 * nx, y + side * 0.04 * ny);
            expect(backing.height).toBeCloseTo(0.025 * p.relief, 12);
            expect(link.height - backing.height).toBeGreaterThan(0.001);
            expect(link.color - backing.color).toBeGreaterThan(0.53);
            expect(link.occlusion - backing.occlusion).toBeGreaterThan(0.51);
          }
        }
      }
    },
  );
  it('keeps compact spherical rims, hidden connector-owner changes, columns and wrap C1', () => {
    const h = 1e-8;
    for (const seed of [0, 1, 0xffffffff]) {
      const at = field(seed);
      for (let y = 0; y <= 128; y++)
        for (let x = 0; x <= 128; x++)
          for (const axis of [0, 1]) {
            const u = (x * p.columns) / 128,
              v = (y * p.rows * p.pitch) / 128,
              a = at(u - (axis ? 0 : h), v - (axis ? h : 0)),
              b = at(u, v),
              c = at(u + (axis ? 0 : h), v + (axis ? h : 0));
            for (const key of [
              'color',
              'height',
              'roughness',
              'occlusion',
            ] as const)
              expect(Math.abs((c[key] - 2 * b[key] + a[key]) / h)).toBeLessThan(
                0.02,
              );
          }
    }
  });
});

describe('Dodecagonal glazed mosaic with two triangular insert families', () => {
  const p = proceduralMaterialPresets.dodecagontiles;
  const field = (seed: number) => {
    const sample = createSurfaceSampler('dodecagontiles', seed);
    return (x: number, y: number): SurfaceSample => {
      const out = {
        color: 0,
        height: 0,
        roughness: 0,
        occlusion: 0,
        mortar: 0,
        metallic: 0,
      };
      sample(x / (p.columns * 2), y / (p.rows * p.rowStep), out);
      return out;
    };
  };
  it.each([0, 1, 0xffffffff])(
    'preserves twelve distinct beveled edges, pale triangular inserts and coplanar glaze for seed %s',
    (seed) => {
      const at = field(seed),
        triangleRadius = 2 / p.rowStep - 1;
      for (let row = 0; row < p.rows; row++)
        for (let col = 0; col < p.columns; col++) {
          const x = col * 2 + (row & 1),
            y = row * p.rowStep,
            center = at(x, y);
          expect(center.mortar).toBe(0);
          expect(center.metallic).toBe(0);
          for (let i = 0; i < 12; i++) {
            const a = (i * Math.PI) / 6,
              c = Math.cos(a),
              s = Math.sin(a),
              face = at(x + 0.88 * c, y + 0.88 * s),
              bevel = at(x + 0.971 * c, y + 0.971 * s),
              grout = at(x + c, y + s);
            expect(face.mortar).toBe(0);
            expect(bevel.mortar).toBeGreaterThan(0);
            expect(bevel.mortar).toBeLessThan(1);
            expect(grout.mortar).toBe(1);
            expect(face.height - grout.height).toBeGreaterThan(0.005);
            expect(grout.roughness - face.roughness).toBeGreaterThan(0.43);
            expect(face.occlusion - grout.occlusion).toBeGreaterThan(0.48);
            expect(Math.abs(face.color - center.color)).toBeLessThan(0.013);
          }
          for (let family = 0; family < 2; family++) {
            const tx = x + 1 - family,
              ty = (row + (family + 1) / 3) * p.rowStep,
              triangle = at(tx, ty);
            expect(triangle.mortar).toBe(0);
            expect(triangle.color - center.color).toBeGreaterThan(0.14);
            expect(Math.abs(triangle.height - center.height)).toBeLessThan(
              0.00004,
            );
            for (let i = 0; i < 3; i++) {
              const a =
                  (family ? -Math.PI / 2 : Math.PI / 2) + (i * 2 * Math.PI) / 3,
                c = Math.cos(a),
                s = Math.sin(a),
                inside = at(
                  tx + triangleRadius * 0.5 * c,
                  ty + triangleRadius * 0.5 * s,
                ),
                seam = at(tx + triangleRadius * c, ty + triangleRadius * s),
                neighbor = at(
                  tx + (triangleRadius + 0.08) * c,
                  ty + (triangleRadius + 0.08) * s,
                );
              expect(inside.mortar).toBe(0);
              expect(seam.mortar).toBe(1);
              expect(neighbor.mortar).toBe(0);
              expect(Math.abs(inside.color - triangle.color)).toBeLessThan(
                0.013,
              );
              expect(inside.color - neighbor.color).toBeGreaterThan(0.14);
              expect(Math.abs(inside.height - neighbor.height)).toBeLessThan(
                0.00004,
              );
            }
          }
        }
    },
  );
  it('keeps twelve-plane clips, both triangle families, nearest-column owners and periodic wrap C1', () => {
    const h = 1e-8;
    for (const seed of [0, 1, 0xffffffff]) {
      const at = field(seed);
      for (let y = 0; y <= 128; y++)
        for (let x = 0; x <= 128; x++)
          for (const axis of [0, 1]) {
            const u = (x * p.columns * 2) / 128,
              v = (y * p.rows * p.rowStep) / 128,
              a = at(u - (axis ? 0 : h), v - (axis ? h : 0)),
              b = at(u, v),
              c = at(u + (axis ? 0 : h), v + (axis ? h : 0));
            for (const key of [
              'color',
              'height',
              'roughness',
              'occlusion',
              'mortar',
            ] as const)
              expect(Math.abs((c[key] - 2 * b[key] + a[key]) / h)).toBeLessThan(
                0.02,
              );
          }
    }
  });
});

describe('Flat brass door keys with bored bows and three bittings', () => {
  const p = proceduralMaterialPresets.doorkeys;
  const field = (seed: number) => {
    const sample = createSurfaceSampler('doorkeys', seed);
    return (x: number, y: number): SurfaceSample => {
      const out = {
        color: 0,
        height: 0,
        roughness: 0,
        occlusion: 0,
        mortar: 0,
        metallic: 0,
      };
      sample(x / p.cells, y / p.cells, out);
      return out;
    };
  };
  it.each([0, 1, 0xffffffff])(
    'preserves continuous flat keys, circular bows, three open bittings, recessed grooves and chamfered tips for seed %s',
    (seed) => {
      const at = field(seed);
      for (let row = 0; row < p.cells; row++)
        for (let col = 0; col < p.cells; col++) {
          const candidates = [0, 1, 2, 3].map((turn) => {
            const a = (turn * Math.PI) / 2,
              c = Math.cos(a),
              s = Math.sin(a);
            return (x: number, y: number) =>
              at(col + 0.5 + x * c - y * s, row + 0.5 + x * s + y * c);
          });
          const poses = candidates.filter(
            (probe) =>
              probe(0, p.bowY - 0.12).height > 0.0024 &&
              probe(0, 0).height > 0.0024,
          );
          expect(poses).toHaveLength(1);
          const probe = poses[0];
          for (let i = 0; i < 32; i++) {
            const a = (i * 2 * Math.PI) / 32,
              c = Math.cos(a),
              s = Math.sin(a),
              crown = probe(0.11 * c, p.bowY + 0.11 * s),
              bore = probe(0.03 * c, p.bowY + 0.03 * s);
            expect(crown.height - bore.height).toBeGreaterThan(0.0023);
            expect(crown.color - bore.color).toBeGreaterThan(0.72);
            expect(bore.roughness - crown.roughness).toBeGreaterThan(0.15);
            expect(crown.occlusion - bore.occlusion).toBeGreaterThan(0.54);
            expect(bore.height).toBeCloseTo(0.025 * p.relief, 12);
            expect(crown.metallic).toBe(1);
          }
          for (let i = 0; i <= 33; i++)
            expect(probe(0, -0.09 + i * 0.01).height).toBeGreaterThan(0.0024);
          for (let i = 0; i < 3; i++) {
            const y = p.firstBitting + i * p.bittingPitch,
              gap = probe(0.06, y),
              tooth = probe(0.06, y + p.bittingPitch * 0.5),
              rail = probe(-0.03, y);
            expect(gap.height).toBeCloseTo(0.025 * p.relief, 12);
            expect(tooth.height - gap.height).toBeGreaterThan(0.0023);
            expect(tooth.occlusion - gap.occlusion).toBeGreaterThan(0.54);
            expect(rail.height).toBeGreaterThan(0.0024);
          }
          const groove = probe(p.grooveX, 0.15);
          for (const x of [-0.033, 0.005]) {
            const flat = probe(x, 0.15);
            expect(flat.height - groove.height).toBeGreaterThan(0.00018);
            expect(flat.color - groove.color).toBeGreaterThan(0.07);
            expect(groove.roughness - flat.roughness).toBeGreaterThan(0.04);
          }
          expect(probe(0.085, 0.275).height).toBeCloseTo(0.025 * p.relief, 12);
          expect(probe(0.04, 0.26).height).toBeGreaterThan(0.0024);
        }
    },
  );
  it('keeps bow/blank unions, bore, bitting owners, grooves, bevels and periodic wrap C1', () => {
    const h = 1e-8;
    for (const seed of [0, 1, 0xffffffff]) {
      const at = field(seed);
      for (let y = 0; y <= 128; y++)
        for (let x = 0; x <= 128; x++)
          for (const axis of [0, 1]) {
            const u = (x * p.cells) / 128,
              v = (y * p.cells) / 128,
              a = at(u - (axis ? 0 : h), v - (axis ? h : 0)),
              b = at(u, v),
              c = at(u + (axis ? 0 : h), v + (axis ? h : 0));
            for (const key of [
              'color',
              'height',
              'roughness',
              'occlusion',
            ] as const)
              expect(Math.abs((c[key] - 2 * b[key] + a[key]) / h)).toBeLessThan(
                0.02,
              );
          }
    }
  });
});

describe('Scalloped cream crackers with nine docking pits', () => {
  const p = proceduralMaterialPresets.creamcrackers;
  const field = (seed: number) => {
    const sample = createSurfaceSampler('creamcrackers', seed);
    return (x: number, y: number): SurfaceSample => {
      const out = {
        color: 0,
        height: 0,
        roughness: 0,
        occlusion: 0,
        mortar: 0,
        metallic: 0,
      };
      sample(x / p.cells, y / p.cells, out);
      return out;
    };
  };
  it.each([0, 1, 0xffffffff])(
    'keeps nine deep dark docking pits, intact baked faces and four scalloped borders for seed %s',
    (seed) => {
      const at = field(seed);
      for (let row = 0; row < p.cells; row++)
        for (let col = 0; col < p.cells; col++) {
          const probe = (x: number, y: number) =>
            at(col + 0.5 + x, row + 0.5 + y);
          for (let hy = -1; hy <= 1; hy++)
            for (let hx = -1; hx <= 1; hx++) {
              const x = hx * p.holePitch,
                y = hy * p.holePitch,
                pit = probe(x, y);
              for (let i = 0; i < 16; i++) {
                const a = (i * 2 * Math.PI) / 16,
                  c = Math.cos(a),
                  s = Math.sin(a),
                  bevel = probe(
                    x + p.holeRadius * 0.9 * c,
                    y + p.holeRadius * 0.9 * s,
                  ),
                  face = probe(x + 0.04 * c, y + 0.04 * s);
                expect(face.height - pit.height).toBeGreaterThan(0.00155);
                expect(face.color - pit.color).toBeGreaterThan(0.18);
                expect(pit.roughness - face.roughness).toBeGreaterThan(0.025);
                expect(face.occlusion - pit.occlusion).toBeGreaterThan(0.33);
                expect(bevel.height).toBeGreaterThan(pit.height);
                expect(bevel.height).toBeLessThan(face.height);
                expect(face.metallic).toBe(0);
              }
            }
          for (let side = 0; side < 4; side++) {
            const a = (side * Math.PI) / 2,
              c = Math.cos(a),
              s = Math.sin(a);
            for (let i = 2; i <= 5; i++) {
              const x = (i + 0.5) * p.notchPitch - p.notchOrigin,
                crestX = x + p.notchPitch * 0.5,
                valley = probe(x * c - 0.348 * s, x * s + 0.348 * c),
                crest = probe(crestX * c - 0.348 * s, crestX * s + 0.348 * c);
              expect(valley.height).toBeCloseTo(0.035 * p.relief, 12);
              expect(crest.height - valley.height).toBeGreaterThan(0.0059);
              expect(crest.color - valley.color).toBeGreaterThan(0.48);
              expect(crest.occlusion - valley.occlusion).toBeGreaterThan(0.51);
            }
          }
          expect(probe(0.4, 0.4).height).toBeCloseTo(0.035 * p.relief, 12);
        }
    },
  );
  it('keeps scallops, docking-pit owners, baked blisters, cell borders and wrap C1', () => {
    const h = 1e-8;
    for (const seed of [0, 1, 0xffffffff]) {
      const at = field(seed);
      for (let y = 0; y <= 128; y++)
        for (let x = 0; x <= 128; x++)
          for (const axis of [0, 1]) {
            const u = (x * p.cells) / 128,
              v = (y * p.cells) / 128,
              a = at(u - (axis ? 0 : h), v - (axis ? h : 0)),
              b = at(u, v),
              c = at(u + (axis ? 0 : h), v + (axis ? h : 0));
            for (const key of [
              'color',
              'height',
              'roughness',
              'occlusion',
            ] as const)
              expect(Math.abs((c[key] - 2 * b[key] + a[key]) / h)).toBeLessThan(
                0.02,
              );
          }
    }
  });
});

describe('Tapered dried fig slices with pale seeds inside wrinkled rind', () => {
  const p = proceduralMaterialPresets.driedfigslice;
  const field = (seed: number) => {
    const sample = createSurfaceSampler('driedfigslice', seed);
    return (x: number, y: number): SurfaceSample => {
      const out = {
        color: 0,
        height: 0,
        roughness: 0,
        occlusion: 0,
        mortar: 0,
        metallic: 0,
      };
      sample(x / p.cells, y / p.cells, out);
      return out;
    };
  };
  it.each([0, 1, 0xffffffff])(
    'keeps tapered whole slices, wrinkled tan rind and raised pale seeds confined to brown flesh for seed %s',
    (seed) => {
      const at = field(seed);
      for (let row = 0; row < p.cells; row++)
        for (let col = 0; col < p.cells; col++) {
          const flip = (col + row) & 1 ? -1 : 1;
          const probe = (x: number, y: number) =>
            at(
              col + 0.5 + x * p.width * (1 + p.taper * y) * flip,
              row + 0.5 + (p.centerY + y * p.length) * flip,
            );
          const pulp = probe(0, 0);
          expect(pulp.color).toBeLessThan(0.39);
          expect(pulp.metallic).toBe(0);
          for (let i = 0; i < 48; i++) {
            const a = (i * 2 * Math.PI) / 48,
              c = Math.cos(a),
              s = Math.sin(a),
              rind = probe(0.92 * c, 0.92 * s),
              bevel = probe(0.975 * c, 0.975 * s),
              edge = probe(c, s),
              outside = probe(1.12 * c, 1.12 * s);
            expect(rind.height - outside.height).toBeGreaterThan(0.0069);
            expect(bevel.height).toBeGreaterThan(outside.height);
            expect(bevel.height).toBeLessThan(rind.height);
            expect(edge.height).toBeCloseTo(0.03 * p.relief, 12);
            expect(outside.height).toBeCloseTo(0.03 * p.relief, 12);
            expect(rind.color).toBeLessThan(0.65);
            expect(rind.roughness - pulp.roughness).toBeGreaterThan(0.079);
            expect(rind.occlusion - outside.occlusion).toBeGreaterThan(0.47);
          }
          for (let sy = 0; sy < p.seeds; sy++)
            for (let sx = 0; sx < p.seeds; sx++) {
              const x = -1 + ((sx + 0.5) * 2) / p.seeds,
                y = -1 + ((sy + 0.5) * 2) / p.seeds;
              if (x * x + y * y >= 0.55 * 0.55) continue;
              let peak = pulp;
              for (let iy = 0; iy <= 10; iy++)
                for (let ix = 0; ix <= 10; ix++) {
                  const value = probe(
                    x + ((ix / 10 - 0.5) * 2) / p.seeds,
                    y + ((iy / 10 - 0.5) * 2) / p.seeds,
                  );
                  if (value.color > peak.color) peak = value;
                }
              const between = probe(x - 1 / p.seeds, y - 1 / p.seeds);
              expect(peak.color).toBeGreaterThan(0.93);
              expect(peak.color - between.color).toBeGreaterThan(0.54);
              expect(peak.height - between.height).toBeGreaterThan(0.00025);
              expect(between.roughness - peak.roughness).toBeGreaterThan(0.11);
              expect(peak.occlusion - between.occlusion).toBeGreaterThan(0.029);
              expect(peak.metallic).toBe(0);
            }
        }
    },
  );
  it('keeps tapered outlines, annular angular creases, clipped seed owners and periodic wrap C1', () => {
    // Tiny seed bevels have high finite curvature; use a smaller step to
    // distinguish converging gradients from an actual owner-boundary jump.
    const h = 1e-9;
    for (const seed of [0, 1, 0xffffffff]) {
      const at = field(seed);
      for (let y = 0; y <= 128; y++)
        for (let x = 0; x <= 128; x++)
          for (const axis of [0, 1]) {
            const u = (x * p.cells) / 128,
              v = (y * p.cells) / 128,
              a = at(u - (axis ? 0 : h), v - (axis ? h : 0)),
              b = at(u, v),
              c = at(u + (axis ? 0 : h), v + (axis ? h : 0));
            for (const key of [
              'color',
              'height',
              'roughness',
              'occlusion',
            ] as const)
              expect(Math.abs((c[key] - 2 * b[key] + a[key]) / h)).toBeLessThan(
                0.02,
              );
          }
    }
  });
});

describe('Black oxide L-shaped hex keys with flat rod facets', () => {
  const p = proceduralMaterialPresets.hexkeys;
  const field = (seed: number) => {
    const sample = createSurfaceSampler('hexkeys', seed);
    return (x: number, y: number): SurfaceSample => {
      const out = {
        color: 0,
        height: 0,
        roughness: 0,
        occlusion: 0,
        mortar: 0,
        metallic: 0,
      };
      sample(x / p.cells, y / p.cells, out);
      return out;
    };
  };
  it.each([0, 1, 0xffffffff])(
    'keeps unequal arms, continuous round elbows, flat crowns, two side facets and flat cut ends for seed %s',
    (seed) => {
      const at = field(seed);
      for (let row = 0; row < p.cells; row++)
        for (let col = 0; col < p.cells; col++) {
          const candidates = [0, 1, 2, 3].map((turn) => {
            const a = (turn * Math.PI) / 2,
              c = Math.cos(a),
              s = Math.sin(a);
            return (x: number, y: number) =>
              at(col + 0.5 + x * c - y * s, row + 0.5 + x * s + y * c);
          });
          const poses = candidates.filter(
            (probe) =>
              probe(-p.bendRadius, -0.26).height > 0.0049 &&
              probe(0.14, p.bendY + p.bendRadius).height > 0.0049,
          );
          expect(poses).toHaveLength(1);
          const probe = poses[0];
          const section = (x: number, y: number, nx: number, ny: number) => {
            const center = probe(x, y);
            for (const side of [-1, 1]) {
              const flat = probe(
                  x + side * nx * p.width * 0.25,
                  y + side * ny * p.width * 0.25,
                ),
                facet = probe(
                  x + side * nx * p.width * 0.75,
                  y + side * ny * p.width * 0.75,
                ),
                backing = probe(
                  x + side * nx * p.width * 1.45,
                  y + side * ny * p.width * 1.45,
                );
              expect(Math.abs(center.height - flat.height)).toBeLessThan(
                0.00004,
              );
              expect(center.height - facet.height).toBeGreaterThan(0.0007);
              expect(center.color - facet.color).toBeGreaterThan(0.14);
              expect(center.height - backing.height).toBeGreaterThan(0.0048);
              expect(backing.roughness - center.roughness).toBeGreaterThan(
                0.18,
              );
              expect(center.occlusion - backing.occlusion).toBeGreaterThan(
                0.49,
              );
              expect(center.metallic).toBe(1);
              expect(facet.metallic).toBe(1);
            }
          };
          section(-p.bendRadius, -0.12, 1, 0);
          section(0.13, p.bendY + p.bendRadius, 0, 1);
          for (let i = 0; i <= 16; i++) {
            const a = Math.PI * (0.5 + i / 32),
              c = Math.cos(a),
              s = Math.sin(a);
            section(p.bendRadius * c, p.bendY + p.bendRadius * s, c, s);
          }
          for (const point of [
            [-p.bendRadius, p.longEnd],
            [-p.bendRadius, p.longEnd - 0.03],
            [p.shortEnd, p.bendY + p.bendRadius],
            [p.shortEnd + 0.03, p.bendY + p.bendRadius],
            [0, p.bendY],
            [0.12, 0],
          ])
            expect(probe(point[0], point[1]).height).toBeCloseTo(
              0.025 * p.relief,
              12,
            );
          expect(probe(-p.bendRadius, p.longEnd + 0.02).height).toBeGreaterThan(
            0.0049,
          );
          expect(
            probe(p.shortEnd - 0.02, p.bendY + p.bendRadius).height,
          ).toBeGreaterThan(0.0049);
        }
    },
  );
  it('keeps facet ramps, straight-to-arc joins, end cuts, owners and wrap C1', () => {
    const h = 1e-8;
    for (const seed of [0, 1, 0xffffffff]) {
      const at = field(seed);
      const check = (x: number, y: number) => {
        for (const axis of [0, 1]) {
          const a = at(x - (axis ? 0 : h), y - (axis ? h : 0)),
            b = at(x, y),
            c = at(x + (axis ? 0 : h), y + (axis ? h : 0));
          for (const key of [
            'color',
            'height',
            'roughness',
            'occlusion',
          ] as const)
            expect(Math.abs((c[key] - 2 * b[key] + a[key]) / h)).toBeLessThan(
              0.02,
            );
        }
      };
      for (let y = 0; y <= 128; y++)
        for (let x = 0; x <= 128; x++)
          check((x * p.cells) / 128, (y * p.cells) / 128);
      for (let row = 0; row < p.cells; row++)
        for (let col = 0; col < p.cells; col++)
          for (let turn = 0; turn < 4; turn++) {
            const a = (turn * Math.PI) / 2,
              c = Math.cos(a),
              s = Math.sin(a);
            for (let i = -12; i <= 12; i++) {
              const d = (i * p.width) / 12;
              for (const [x, y] of [
                [-p.bendRadius + d, p.bendY],
                [0, p.bendY + p.bendRadius + d],
              ])
                check(col + 0.5 + x * c - y * s, row + 0.5 + x * s + y * c);
            }
          }
    }
  });
});

describe('Interlocking fish-scale glazed mosaic tiles', () => {
  const p = proceduralMaterialPresets.fishscaletiles;
  const field = (seed: number) => {
    const sample = createSurfaceSampler('fishscaletiles', seed);
    return (x: number, y: number): SurfaceSample => {
      const out = {
        color: 0,
        height: 0,
        roughness: 0,
        occlusion: 0,
        mortar: 0,
        metallic: 0,
      };
      sample(x / (p.columns * 2), y / p.rows, out);
      return out;
    };
  };
  it.each([0, 1, 0xffffffff])(
    'preserves convex fan tops, two concave lower grout arcs and coplanar seeded glaze for seed %s',
    (seed) => {
      const at = field(seed);
      for (let row = 0; row < p.rows; row++)
        for (let col = 0; col < p.columns; col++) {
          const x = col * 2 + (row & 1),
            face = at(x, row - 0.35),
            lower = at(x, row + 0.35);
          expect(face.mortar).toBe(0);
          expect(lower.mortar).toBe(0);
          expect(Math.abs(face.color - lower.color)).toBeLessThan(0.013);
          expect(Math.abs(face.height - lower.height)).toBeLessThan(0.00004);
          expect(face.metallic).toBe(0);
          for (let i = 0; i <= 16; i++) {
            const a = Math.PI * (1.1 + (0.8 * i) / 16),
              c = Math.cos(a),
              s = Math.sin(a),
              inner = at(x + 0.84 * c, row + 0.84 * s),
              bevel = at(x + 0.95 * c, row + 0.95 * s),
              grout = at(x + c, row + s);
            expect(inner.mortar).toBe(0);
            expect(bevel.mortar).toBeGreaterThan(0);
            expect(bevel.mortar).toBeLessThan(1);
            expect(grout.mortar).toBe(1);
            expect(inner.height - grout.height).toBeGreaterThan(0.0049);
            expect(grout.roughness - inner.roughness).toBeGreaterThan(0.46);
            expect(inner.occlusion - grout.occlusion).toBeGreaterThan(0.48);
          }
          for (const side of [-1, 1])
            for (let i = 0; i <= 8; i++) {
              const a = Math.PI * (7 / 6 + i / 48),
                c = Math.cos(a),
                s = Math.sin(a),
                next = at(x + side, row + 0.65),
                seam = at(x + side * (1 + c), row + 1 + s),
                original = at(x + side * (1 + 1.12 * c), row + 1 + 1.12 * s),
                neighbor = at(x + side * (1 + 0.85 * c), row + 1 + 0.85 * s);
              expect(seam.mortar).toBe(1);
              expect(original.mortar).toBe(0);
              expect(neighbor.mortar).toBe(0);
              expect(Math.abs(original.color - face.color)).toBeLessThan(0.013);
              expect(Math.abs(neighbor.color - next.color)).toBeLessThan(0.013);
            }
        }
    },
  );
  it('keeps curved grout, nearest-disk ties, row ownership and periodic wrap C1', () => {
    const h = 1e-8;
    for (const seed of [0, 1, 0xffffffff]) {
      const at = field(seed);
      for (let y = 0; y <= 128; y++)
        for (let x = 0; x <= 128; x++)
          for (const axis of [0, 1]) {
            const u = (x * p.columns * 2) / 128,
              v = (y * p.rows) / 128,
              a = at(u - (axis ? 0 : h), v - (axis ? h : 0)),
              b = at(u, v),
              c = at(u + (axis ? 0 : h), v + (axis ? h : 0));
            for (const key of [
              'color',
              'height',
              'roughness',
              'occlusion',
              'mortar',
            ] as const)
              expect(Math.abs((c[key] - 2 * b[key] + a[key]) / h)).toBeLessThan(
                0.02,
              );
          }
    }
  });
});

