describe('Cross-bedded sandstone with alternating curved dip sets', () => {
  const p = proceduralMaterialPresets.crossbeddedsandstone;
  const field = (seed: number) => {
    const sample = createSurfaceSampler('crossbeddedsandstone', seed);
    return (x: number, y: number): SurfaceSample => {
      const out = {
        color: 0,
        height: 0,
        roughness: 0,
        occlusion: 0,
        mortar: 0,
        metallic: 0,
      };
      sample(x, y / p.beds, out);
      return out;
    };
  };
  it.each([0, 1, 0xffffffff])(
    'retains inclined curved laminae with alternating dip, recessed fine bands and common horizontal terminations for seed %s',
    (seed) => {
      const at = field(seed);
      for (let row = 0; row < p.beds; row++) {
        const sign = row & 1 ? -1 : 1,
          minimum = (
            y: number,
            center: number,
            radius: number,
            steps: number,
          ) => {
            let x = center - radius,
              sample = at(x, row + 0.5 + y);
            for (let i = 1; i <= steps; i++) {
              const nextX = center - radius + (2 * radius * i) / steps,
                next = at(nextX, row + 0.5 + y);
              if (next.occlusion < sample.occlusion) {
                x = nextX;
                sample = next;
              }
            }
            return { x, sample };
          },
          center = minimum(
            0,
            0.5 / p.laminaFrequency,
            0.5 / p.laminaFrequency,
            1024,
          ),
          upper = minimum(0.06, center.x, 0.04, 512),
          lower = minimum(-0.06, center.x, 0.04, 512),
          upperCurve = minimum(0.12, center.x - sign * 0.054, 0.015, 512),
          lowerCurve = minimum(-0.12, center.x + sign * 0.054, 0.015, 512),
          curvature = sign * (upperCurve.x + lowerCurve.x - 2 * center.x),
          flat = at(center.x + 0.5 / p.laminaFrequency, row + 0.5);
        expect(sign * (upper.x - center.x)).toBeLessThan(-0.023);
        expect(sign * (upper.x - center.x)).toBeGreaterThan(-0.031);
        expect(sign * (lower.x - center.x)).toBeGreaterThan(0.023);
        expect(sign * (lower.x - center.x)).toBeLessThan(0.031);
        expect(curvature).toBeLessThan(-0.0005);
        expect(curvature).toBeGreaterThan(-0.002);
        expect(flat.color - center.sample.color).toBeGreaterThan(0.16);
        expect(flat.height - center.sample.height).toBeGreaterThan(0.00054);
        expect(center.sample.roughness - flat.roughness).toBeGreaterThan(0.014);
        expect(flat.occlusion - center.sample.occlusion).toBeGreaterThan(0.034);
        expect(center.sample.metallic).toBe(0);
        for (let i = 0; i <= 32; i++) {
          const horizon = at(i / 32, row),
            host = at(i / 32, row + 0.045);
          expect(host.occlusion).toBe(0.97);
          expect(horizon.occlusion).toBe(0.95);
          expect(host.color - horizon.color).toBeGreaterThan(0.06);
          expect(host.height - horizon.height).toBeGreaterThan(0.00024);
          expect(horizon.roughness - host.roughness).toBeGreaterThan(0.024);
        }
      }
    },
  );
  it('keeps compact inclined laminae, curved dip profiles, truncated bed owners, contacts and wrap C1', () => {
    const h = 1e-8;
    for (const seed of [0, 1, 0xffffffff]) {
      const at = field(seed);
      for (let y = 0; y <= 128; y++)
        for (let x = 0; x <= 128; x++)
          for (const axis of [0, 1]) {
            const u = x / 128,
              v = (y * p.beds) / 128,
              a = at(u - (axis ? 0 : h), v - (axis ? h : 0)),
              b = at(u, v),
              c = at(u + (axis ? 0 : h), v + (axis ? h : 0));
            for (const key of [
              'color',
              'height',
              'roughness',
              'occlusion',
            ] as const)
              expect(Math.abs((c[key] - 2 * b[key] + a[key]) / h)).toBeLessThan(
                0.02,
              );
          }
    }
  });
});

describe('Three-strand flat braided cords with alternating over-under crossings', () => {
  const p = proceduralMaterialPresets.braidedcord;
  const field = (seed: number) => {
    const sample = createSurfaceSampler('braidedcord', seed);
    return (x: number, y: number): SurfaceSample => {
      const out = {
        color: 0,
        height: 0,
        roughness: 0,
        occlusion: 0,
        mortar: 0,
        metallic: 0,
      };
      sample(x / p.columns, y / p.cycles, out);
      return out;
    };
  };
  it.each([0, 1, 0xffffffff])(
    'alternates the foreground identities of all three strands without losing cord coverage or leaking into column gaps for seed %s',
    (seed) => {
      const at = field(seed);
      for (let col = 0; col < p.columns; col++) {
        for (let cycle = 0; cycle < p.cycles; cycle++) {
          const local = (x: number, y: number) => at(col + 0.5 + x, cycle + y),
            backing = local(0.49, 0),
            crowns: SurfaceSample[] = [];
          for (let i = 0; i < 3; i++) {
            const phase = (1 + 2 * i) / 12,
              side = i === 1 ? -1 : 1,
              crown = local((side * p.amplitude * 41) / 81, phase),
              isolated = local(-side * p.amplitude, phase);
            crowns.push(crown);
            expect(crown.height - isolated.height).toBeGreaterThan(0.0027);
            expect(crown.height - backing.height).toBeGreaterThan(0.013);
            expect(crown.occlusion - backing.occlusion).toBeGreaterThan(0.57);
            expect(backing.roughness - crown.roughness).toBeGreaterThan(0.17);
            expect(crown.metallic).toBe(0);
          }
          expect(crowns[1].color - crowns[0].color).toBeGreaterThan(0.09);
          expect(crowns[2].color - crowns[1].color).toBeGreaterThan(0.09);
          for (let i = 0; i <= 32; i++) {
            expect(local(-0.5, i / 32).height).toBe(backing.height);
            expect(local(0.5, i / 32).height).toBe(backing.height);
          }
        }
        for (let row = 0; row < 16; row++) {
          let groups = 0,
            inside = false;
          for (let i = 0; i <= 256; i++) {
            const raised = at(col + i / 256, row / 16).height > 0.004;
            if (raised && !inside) groups++;
            inside = raised;
          }
          expect(groups).toBeGreaterThanOrEqual(2);
          expect(groups).toBeLessThanOrEqual(3);
        }
      }
    },
  );
  it('keeps piecewise-quartic plait paths, convex strands, smooth depth ownership and UV wrap C1', () => {
    const h = 1e-8;
    for (const seed of [0, 1, 0xffffffff]) {
      const at = field(seed);
      for (let y = 0; y <= 128; y++)
        for (let x = 0; x <= 128; x++)
          for (const axis of [0, 1]) {
            const u = (x * p.columns) / 128,
              v = (y * p.cycles) / 128,
              a = at(u - (axis ? 0 : h), v - (axis ? h : 0)),
              b = at(u, v),
              c = at(u + (axis ? 0 : h), v + (axis ? h : 0));
            for (const key of [
              'color',
              'height',
              'roughness',
              'occlusion',
            ] as const)
              expect(Math.abs((c[key] - 2 * b[key] + a[key]) / h)).toBeLessThan(
                0.02,
              );
          }
    }
  });
});

describe('Thin punched paper cards with a clipped corner', () => {
  const p = proceduralMaterialPresets.punchcard;
  const field = (seed: number) => {
    const sample = createSurfaceSampler('punchcard', seed);
    return (x: number, y: number): SurfaceSample => {
      const out = {
        color: 0,
        height: 0,
        roughness: 0,
        occlusion: 0,
        mortar: 0,
        metallic: 0,
      };
      sample(x / p.columns, y / p.rows, out);
      return out;
    };
  };
  it.each([0, 1, 0xffffffff])(
    'retains two rectangular punches per column, paper webs, a single clipped upper corner and thin card relief for seed %s',
    (seed) => {
      const at = field(seed);
      for (let cardRow = 0; cardRow < p.rows; cardRow++)
        for (let cardCol = 0; cardCol < p.columns; cardCol++) {
          const local = (x: number, y: number) =>
              at(cardCol + 0.5 + x, cardRow + 0.5 + y),
            backing = local(0.48, 0),
            paper = local(-0.4, -0.36);
          expect(paper.height - backing.height).toBeGreaterThan(0.00029);
          expect(paper.height - backing.height).toBeLessThan(0.00031);
          expect(local(0.4, -0.36).height).toBe(backing.height);
          expect(local(0.4, 0.36).height - backing.height).toBeGreaterThan(
            0.00029,
          );
          for (let col = 0; col < p.punchColumns; col++) {
            let punches = 0;
            const x = (col - (p.punchColumns - 1) / 2) * p.pitchX;
            for (let row = 0; row < p.punchRows; row++) {
              const y = (row - (p.punchRows - 1) / 2) * p.pitchY,
                center = local(x, y),
                web = local(x + p.pitchX / 2, y);
              expect(web.height - backing.height).toBeGreaterThan(0.00029);
              if (center.height === backing.height) {
                punches++;
                expect(web.color - center.color).toBeGreaterThan(0.74);
                expect(web.occlusion - center.occlusion).toBeGreaterThan(0.38);
                expect(center.roughness - web.roughness).toBeGreaterThan(0.1);
                expect(center.metallic).toBe(0);
                for (const [dx, dy] of [
                  [p.punchHalfWidth * 0.8, 0],
                  [0, p.punchHalfHeight - p.punchBevel * 0.5],
                ] as const) {
                  const edge = local(x + dx, y + dy);
                  expect(edge.height).toBeGreaterThan(center.height);
                  expect(edge.height).toBeLessThan(web.height);
                }
              } else {
                expect(center.height - backing.height).toBeGreaterThan(0.00029);
              }
            }
            expect(punches).toBe(2);
          }
          for (let i = 0; i <= 32; i++) {
            const t = i / 32;
            for (const [x, y] of [
              [-p.halfWidth, (2 * t - 1) * p.halfHeight],
              [p.halfWidth, (2 * t - 1) * p.halfHeight],
              [(2 * t - 1) * p.halfWidth, -p.halfHeight],
              [(2 * t - 1) * p.halfWidth, p.halfHeight],
            ] as const)
              expect(local(x, y).height).toBe(backing.height);
          }
        }
    },
  );
  it('keeps clipped paper outlines, thin rectangular punch bevels, nearest-slot owners and wrap C1', () => {
    const h = 1e-8;
    for (const seed of [0, 1, 0xffffffff]) {
      const at = field(seed);
      for (let y = 0; y <= 128; y++)
        for (let x = 0; x <= 128; x++)
          for (const axis of [0, 1]) {
            const u = (x * p.columns) / 128,
              v = (y * p.rows) / 128,
              a = at(u - (axis ? 0 : h), v - (axis ? h : 0)),
              b = at(u, v),
              c = at(u + (axis ? 0 : h), v + (axis ? h : 0));
            for (const key of [
              'color',
              'height',
              'roughness',
              'occlusion',
            ] as const)
              expect(Math.abs((c[key] - 2 * b[key] + a[key]) / h)).toBeLessThan(
                0.02,
              );
          }
    }
  });
});

describe('Five-petal cherry blossoms with notched tips and pollen dots', () => {
  const p = proceduralMaterialPresets.cherryblossom;
  const field = (seed: number) => {
    const sample = createSurfaceSampler('cherryblossom', seed);
    return (x: number, y: number): SurfaceSample => {
      const out = {
        color: 0,
        height: 0,
        roughness: 0,
        occlusion: 0,
        mortar: 0,
        metallic: 0,
      };
      sample(x / p.cells, y / p.cells, out);
      return out;
    };
  };
  it.each([0, 1, 0xffffffff])(
    'retains five connected split-tip petals, intervening gaps, a lower heart and twelve raised pale pollen dots for seed %s',
    (seed) => {
      const at = field(seed);
      for (let row = 0; row < p.cells; row++)
        for (let col = 0; col < p.cells; col++) {
          const turn = (((col + row) & 1) * Math.PI) / p.petals,
            c = Math.cos(turn),
            s = Math.sin(turn),
            local = (x: number, y: number) =>
              at(col + 0.5 + x * c - y * s, row + 0.5 + x * s + y * c),
            backing = local(0.44, 0),
            center = local(0, 0);
          expect(local(0.18, 0).height - center.height).toBeGreaterThan(0.0024);
          for (let i = 0; i < p.petals; i++) {
            const a = (i * 2 * Math.PI) / p.petals,
              c = Math.cos(a),
              s = Math.sin(a),
              petal = (x: number, y: number) =>
                local(x * c - y * s, x * s + y * c),
              notch = petal(0.34, 0),
              gap = local(
                0.3 * Math.cos(a + Math.PI / p.petals),
                0.3 * Math.sin(a + Math.PI / p.petals),
              );
            expect(notch.height).toBe(backing.height);
            expect(gap.height).toBe(backing.height);
            for (const side of [-1, 1]) {
              const lobe = petal(0.3, 0.045 * side);
              expect(lobe.height - notch.height).toBeGreaterThan(0.007);
              expect(lobe.color - notch.color).toBeGreaterThan(0.6);
              expect(lobe.occlusion - notch.occlusion).toBeGreaterThan(0.55);
              expect(lobe.metallic).toBe(0);
            }
            for (let j = 0; j <= 32; j++)
              expect(
                petal((0.28 * j) / 32, 0).height - backing.height,
              ).toBeGreaterThan(0.006);
          }
          for (let i = 0; i < p.pollenCount; i++) {
            const a = (i * 2 * Math.PI) / p.pollenCount,
              b = a + Math.PI / p.pollenCount,
              dot = local(
                p.pollenDistance * Math.cos(a),
                p.pollenDistance * Math.sin(a),
              ),
              gap = local(
                p.pollenDistance * Math.cos(b),
                p.pollenDistance * Math.sin(b),
              );
            expect(dot.height - gap.height).toBeGreaterThan(0.0013);
            expect(dot.color - gap.color).toBeGreaterThan(0.18);
            expect(dot.occlusion - gap.occlusion).toBeGreaterThan(0.039);
          }
        }
    },
  );
  it('keeps petal unions, split tip subtractions, pollen support gate, heart and wrap C1', () => {
    const h = 1e-8;
    for (const seed of [0, 1, 0xffffffff]) {
      const at = field(seed);
      for (let y = 0; y <= 128; y++)
        for (let x = 0; x <= 128; x++)
          for (const axis of [0, 1]) {
            const u = (x * p.cells) / 128,
              v = (y * p.cells) / 128,
              a = at(u - (axis ? 0 : h), v - (axis ? h : 0)),
              b = at(u, v),
              c = at(u + (axis ? 0 : h), v + (axis ? h : 0));
            for (const key of [
              'color',
              'height',
              'roughness',
              'occlusion',
            ] as const)
              expect(Math.abs((c[key] - 2 * b[key] + a[key]) / h)).toBeLessThan(
                0.02,
              );
          }
    }
  });
});

describe('Blue-grey and cream right-triangle glazed tiles', () => {
  const p = proceduralMaterialPresets.righttriangletiles;
  const field = (seed: number) => {
    const sample = createSurfaceSampler('righttriangletiles', seed);
    return (x: number, y: number): SurfaceSample => {
      const out = {
        color: 0,
        height: 0,
        roughness: 0,
        occlusion: 0,
        mortar: 0,
        metallic: 0,
      };
      sample(x / p.cells, y / p.cells, out);
      return out;
    };
  };
  it.each([0, 1, 0xffffffff])(
    'keeps 32 independently shaded triangular faces, alternating diagonals and smooth equal-width grout bevels for seed %s',
    (seed) => {
      const at = field(seed);
      for (let row = 0; row < p.cells; row++)
        for (let col = 0; col < p.cells; col++) {
          const local = (x: number, y: number) =>
              at(col + x, row + ((col + row) & 1 ? 1 - y : y)),
            dark = local(2 / 3, 1 / 3),
            light = local(1 / 3, 2 / 3),
            grout = local(0.5, 0.5);
          expect(light.color - dark.color).toBeGreaterThan(0.29);
          for (const face of [dark, light]) {
            expect(face.height - grout.height).toBeGreaterThan(0.02);
            expect(face.occlusion - grout.occlusion).toBeGreaterThan(0.47);
            expect(grout.roughness - face.roughness).toBeGreaterThan(0.46);
            expect(face.mortar).toBe(0);
            expect(face.metallic).toBe(0);
          }
          for (let i = 0; i <= 32; i++) {
            const t = i / 32;
            for (const [x, y] of [
              [t, t],
              [0, t],
              [1, t],
              [t, 0],
              [t, 1],
            ] as const) {
              const seam = local(x, y);
              expect(seam.height).toBe(grout.height);
              expect(seam.mortar).toBe(1);
            }
          }
          for (const side of [-1, 1]) {
            let previous = grout.height;
            for (const distance of [0.04, 0.055, 0.09]) {
              const offset = side * distance * Math.SQRT1_2,
                diagonal = local(0.5 + offset, 0.5 - offset),
                straight = local(distance, 0.3);
              expect(diagonal.height - previous).toBeGreaterThan(0.004);
              expect(Math.abs(diagonal.height - straight.height)).toBeLessThan(
                0.00018,
              );
              previous = diagonal.height;
            }
          }
        }
    },
  );
  it('keeps triangle half-planes, seeded pigments, alternating diagonal owners, grid corners and wrap C1', () => {
    const h = 1e-8;
    for (const seed of [0, 1, 0xffffffff]) {
      const at = field(seed);
      for (let y = 0; y <= 128; y++)
        for (let x = 0; x <= 128; x++)
          for (const axis of [0, 1]) {
            const u = (x * p.cells) / 128,
              v = (y * p.cells) / 128,
              a = at(u - (axis ? 0 : h), v - (axis ? h : 0)),
              b = at(u, v),
              c = at(u + (axis ? 0 : h), v + (axis ? h : 0));
            for (const key of [
              'color',
              'height',
              'roughness',
              'occlusion',
              'mortar',
            ] as const)
              expect(Math.abs((c[key] - 2 * b[key] + a[key]) / h)).toBeLessThan(
                0.02,
              );
          }
    }
  });
});

