        angle = 2 * Math.PI * hash(x, y, seed ^ 0x5f39),
        cells = kind === 'rice' ? 12 : kind === 'sesame' ? 16 : 8,
        length =
          kind === 'rice'
            ? 0.62 + 0.09 * variation
            : kind === 'sesame'
              ? 0.48 + 0.06 * variation
              : 0.57 + 0.06 * variation,
        width =
          kind === 'rice'
            ? 0.14 + 0.025 * variation
            : kind === 'sesame'
              ? 0.24 + 0.025 * variation
              : 0.36 + 0.03 * variation;
