              v = (y + 0.5) / 128;
            sample(u, v, a);
            sample(u + 1 / 128, v, b);
            transverse += (a[field] - b[field]) ** 2;
            sample(u, v + 1 / 128, b);
            longitudinal += (a[field] - b[field]) ** 2;
