      size,
      invalid,
      level,
      bodies,
      bodyVoids,
      pins,
      plates,
      basins,
      minHeight,
      maxHeight,
      plateLevel,
      sample,
      colors,
      heights,
      metals,
      bodyMask,
      plateMask,
      bodyLabels,
      pinLabels,
      plateLabels,
      basinLabels,
