        expect(s.commonPlastic).toBeLessThan(0.035);
        expect(s.contrast).toBeGreaterThan(0.3);
        expect(s.wellDepth).toBeGreaterThan(0.15);
        expect(s.tongueLift).toBeGreaterThan(0.12);
        expect(s.padLift).toBeGreaterThan(0.015);
